#!/usr/bin/env python3
"""Builds 24 original transparent SVG and PNG teaching vignettes for Tongue Twisters.

The complete source artwork is stored as a compressed, reproducible Python drawing
recipe below so the deploy pipeline creates locally hosted PNG assets. Run this file
with Python after installing cairosvg.
"""
from base64 import b64decode
from zlib import decompress
_ARTWORK_RECIPE = ""
exec(compile(decompress(b64decode(_ARTWORK_RECIPE)), __file__, 'exec'))
